\documentclass[tikz, border=5mm]{standalone}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows, intersections} 
\usepgfplotslibrary{fillbetween}

\begin{document}

\pagestyle{empty} 

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{tikzpicture}
[
declare function={f(\x) = e^(-0.9*((\x-\myMean)/\mySTD)^2)+\offsetplot;}
]

% Randomness
\pgfmathsetseed{5}
\def\spread{0.05}

\def\myMean{50}
\def\mySTD{2}

% Number of buckets
\def\N{40}

% Color
\def\mycolor{darkgreen}

%%% =========================

% Technical
\def\offsetplot{0.02}
% Mins and maxs for the data 
\pgfmathsetmacro{\myMin}{\myMean-4*\mySTD};
\pgfmathsetmacro{\myMax}{\myMean+4*\mySTD};
% Mins and Maxs for the x-axis
\pgfmathsetmacro{\myXMin}{\myMean-5.5*\mySTD};
\pgfmathsetmacro{\myXMax}{\myMean+5.5*\mySTD};


\begin{axis}[
clip=false,
trig format plots=rad,
tick label style={font=\footnotesize},
label style={font=\small},
tick style={draw=black, thick},
axis line style = {thick},
axis y line = center,
axis x line = middle,
%axis equal, %grid = both,
xmin = {\myXMin},
xmax = {\myXMax},
ymin = {0},
ymax = {1.5},    
xtick = {45,50,55},
xticklabels = {$60$,$70$,$80$},
ytick = {0}, %yticklabels = {},  
xlabel = {}, axis x discontinuity=crunch, %crunch|parallel|none
ylabel = {}, %axis y discontinuity=crunch, %crunch|parallel|none
%x tick label style={xshift={(\tick==-5)*-5pt}},
xlabel style={below right}, ylabel style={above right},
every axis x label/.style={at={(ticklabel* cs:1.02)},anchor=west,},
every axis y label/.style={at={(ticklabel* cs:1.02)},anchor=south,}
]

% Histogram (distribution)
\foreach \x [evaluate=\x as \y using f(\myMin+(\myMax-\myMin)/\N*(\x-0.4))] in {1,2,...,\N}{
	\edef\temp{
		\noexpand\draw[ultra thin, color=white, opacity=0.1, fill=\mycolor!70, fill opacity=0.5] 
			(axis cs: {\myMin+(\myMax-\myMin)/\N*(\x-0.4)-(\myMax-\myMin)/(2*\N)}, {\offsetplot/2}) 
				rectangle 
			(axis cs: {\myMin+(\myMax-\myMin)/\N*(\x-0.4)+(\myMax-\myMin)/(2*\N)}, {\y+(rand+1)/2*\spread});
	}\temp
}

% Curve
\plot[domain={\myMin}:{\myMax}, samples=200, color=deepskyblue, very thick] {f(\x)};

\end{axis}
\end{tikzpicture}
\end{document}

